const content = (msg.payload && msg.payload.content) ? String(msg.payload.content).trim() : '';
const chatId = msg.payload.chatId;
const stateKey = 'calc_state_' + chatId;
const state = flow.get(stateKey) || 'menu';

function log(step, detail) {
    node.warn(`[${new Date().toISOString()}] chatId=${chatId} step=${step} :: ${detail}`);
}

const buttons = [
    { type: 'postback', label: '🧮 Калькулятор', value: 'menu_calc' },
    { type: 'postback', label: '💱 Курс валют', value: 'menu_currency' },
    { type: 'postback', label: 'ℹ️ Про бота', value: 'menu_about' }
];

if (content === '/start' || content === '/menu' || content === 'back') {
    flow.set(stateKey, 'menu');
    return [{ ...msg, payload: { type: 'inline-buttons', chatId, content: 'Головне меню. Обери пункт:', buttons } }, null, null];
}

if (content === 'menu_calc') {
    flow.set(stateKey, 'awaiting_calc');
    return [{ ...msg, payload: { type: 'message', chatId,
        content: 'Введи вираз у форматі "число оператор число", наприклад: 12 + 7\nОператори: + − * / (або × ÷)\n\n/menu — повернутись у меню' } }, null, null];
}

if (content === 'menu_currency') {
    flow.set(stateKey, 'menu');
    log('nbu:request_sent', 'calling NBU API');
    return [null, null, { ...msg, chatId }];
}

if (content === 'menu_about') {
    flow.set(stateKey, 'menu');
    return [{ ...msg, payload: { type: 'message', chatId,
        content: 'ℹ️ Тестовий бот NovaIT.\nРахує вирази та показує курс валют з API НБУ.\n\n/menu — головне меню' } }, null, null];
}

if (state === 'awaiting_calc') {
    return [null, { ...msg, chatId }, null];
}

return [{ ...msg, payload: { type: 'inline-buttons', chatId, content: 'Не зрозумів ваш запит. Оберіть пункт повторно:', buttons } }, null, null];

const chatId = msg.chatId;
const raw = (msg.payload && msg.payload.content) ? String(msg.payload.content).trim() : '';

node.warn(`[${new Date().toISOString()}] chatId=${chatId} step=calc:input_received :: raw="${raw}"`);

if (raw.length === 0) {
    node.warn(`[${new Date().toISOString()}] chatId=${chatId} step=calc:validation_error :: empty input`);
    msg.payload = { type: 'message', chatId, content: '⚠️ Повідомлення порожнє. Введи вираз, наприклад: 12 + 7' };
    return msg;
}

if (raw.length > 50) {
    node.warn(`[${new Date().toISOString()}] chatId=${chatId} step=calc:validation_error :: input too long`);
    msg.payload = { type: 'message', chatId, content: '⚠️ Занадто довгий ввід. Спробуй коротше, наприклад: 12 + 7' };
    return msg;
}

const clean = raw.replace(/\s+/g, ''); // прибираємо всі пробіли — "8*8" і "8 * 8" стають однаковими
const match = clean.match(/^(\d+(?:[.,]\d+)?)([+\-*/×÷])(\d+(?:[.,]\d+)?)$/);

if (!match) {
    node.warn(`[${new Date().toISOString()}] chatId=${chatId} step=calc:validation_error :: unrecognized format`);
    msg.payload = { type: 'message', chatId, content: '⚠️ Не розпізнав вираз. Формат: число оператор число, наприклад: 12 + 7 або 8*8' };
    return msg;
}

const n1 = Number(match[1].replace(',', '.'));
const op = match[2];
const n2 = Number(match[3].replace(',', '.'));

let result;
if (op === '+') result = n1 + n2;
else if (op === '-' || op === '−') result = n1 - n2;
else if (op === '*' || op === '×') result = n1 * n2;
else {
    if (n2 === 0) {
        node.warn(`[${new Date().toISOString()}] chatId=${chatId} step=calc:validation_error :: division by zero`);
        msg.payload = { type: 'message', chatId, content: '⚠️ Ділення на нуль неможливе. Спробуй інший вираз.' };
        return msg;
    }
    result = n1 / n2;
}

node.warn(`[${new Date().toISOString()}] chatId=${chatId} step=calc:success :: ${n1} ${op} ${n2} = ${result}`);
msg.payload = { type: 'message', chatId, content: `✅ Результат: ${n1} ${op} ${n2} = ${result}\n\nЩе один вираз або /menu` };
return msg;

const chatId = msg.chatId;

node.warn(`[${new Date().toISOString()}] chatId=${chatId} step=nbu:response_received :: statusCode=${msg.statusCode}`);

const data = msg.payload;
const usd = Array.isArray(data) ? data.find(c => c.cc === 'USD') : null;
const eur = Array.isArray(data) ? data.find(c => c.cc === 'EUR') : null;

if (!usd || !eur) {
    node.warn(`[${new Date().toISOString()}] chatId=${chatId} step=nbu:error :: invalid response or USD/EUR missing`);
    msg.payload = { type: 'message', chatId, content: '⚠️ Не вдалося отримати курс, спробуйте пізніше.' };
    return msg;
}

node.warn(`[${new Date().toISOString()}] chatId=${chatId} step=nbu:success :: USD=${usd.rate} EUR=${eur.rate}`);
msg.payload = {
    type: 'message',
    chatId,
    content: `💱 Курс НБУ на ${usd.exchangedate}:\n\nUSD: ${usd.rate.toFixed(4)} грн\nEUR: ${eur.rate.toFixed(4)} грн\n\n/menu — головне меню`
};
return msg;
